script:
frappe.ui.form.on('Email Account', {
    refresh: function(frm) {
        
        if (frm.doc.enable_incoming && !frm.is_new()) {
            frm.add_custom_button(__('📥 Sync Full History'), function() {
                console.log(frm.doc.name, "--test")
                frappe.call({
                    // ✅ Sirf enqueue wala method call karein
                    method: 'vaaman_ats_ai.api.email.tasks.enqueue_full_email_sync',
                    args: { email_account_name: frm.doc.name },
                    callback: function(r) {
                        if (r.message) frappe.msgprint(r.message);
                    }
                });
            }, 'Sync');
        }
    }
});
